<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">   -</span><span style="--shiki-light:#24292E;--shiki-light-font-weight:bold;--shiki-dark:#E1E4E8;--shiki-dark-font-weight:bold;"> **zij**</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> → &quot;zay&quot; (starts with z, distinctive)</span></span>
